}

#[derive(Debug, Clone)]
pub struct ComplianceTrend {
    pub node: SpecNodeData,
    pub data_points: Vec<ComplianceDataPoint>,
    pub trend_direction: String,  // "improving", "degrading", "stable", "unknown"
}

