use chrono::Utc;
use petgraph::graph::{DiGraph, EdgeIndex, NodeIndex};
use petgraph::visit::EdgeRef;
use petgraph::Direction;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use uuid::Uuid;

// Import Z3-based formal verification modules
use crate::udaf::{AdmissibleSet, Constraint, ConstraintKind};
use crate::prover::{Prover, ProofStatus};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum NodeKind {
    Assertion,
    Constraint,
    Scenario,
    Definition,
    Domain,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EdgeKind {
    Refines,
    DependsOn,
    Contradicts,
    DerivesFrom,
    Synonym,
    Composes,
    Formalizes,  // Target is a more formal version of source
    Transform,   // Function f: maps spec from source universe to target universe
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SpecNodeData {
    pub id: String,
    pub content: String,
    pub kind: NodeKind,
    pub metadata: HashMap<String, String>,
    #[serde(default)]
    pub created_at: i64,
    #[serde(default)]
    pub modified_at: i64,
    #[serde(default)]
    pub formality_layer: u8,  // 0=natural, 1=structured, 2=formal, 3=executable
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpecEdgeData {
    pub id: String,
    pub kind: EdgeKind,
    pub metadata: HashMap<String, String>,
    #[serde(default)]
    pub created_at: i64,
}

/// Edge with source/target node IDs (for serialization)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Edge {
    pub source: String,
    pub target: String,
    #[serde(flatten)]
    pub data: SpecEdgeData,
}

#[derive(Debug, Clone)]
pub struct Contradiction {
    pub node_a: SpecNodeData,
    pub node_b: SpecNodeData,
    pub explanation: String,
}

#[derive(Debug, Clone)]
pub struct Omission {
    pub description: String,
    pub related_nodes: Vec<SpecNodeData>,
}

#[derive(Debug, Clone)]
pub struct LayerInconsistency {
    pub source: SpecNodeData,
    pub target: SpecNodeData,
    pub explanation: String,
}

#[derive(Debug, Clone)]
pub struct InterUniverseInconsistency {
    pub universe_a: String,  // Universe identifier (from metadata)
    pub universe_b: String,
    pub spec_a: SpecNodeData,
    pub spec_b: SpecNodeData,
    pub transform_path: Vec<String>,  // Edge IDs forming the transformation path
    pub explanation: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpecGraph {
    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    #[serde(skip)]
    id_to_index: HashMap<String, NodeIndex>,
    #[serde(skip)]
    edge_id_to_index: HashMap<String, EdgeIndex>,
}

impl Default for SpecGraph {
    fn default() -> Self {
        Self::new()
    }
}

impl SpecGraph {
    pub fn new() -> Self {
        Self {
            graph: DiGraph::new(),
            id_to_index: HashMap::new(),
            edge_id_to_index: HashMap::new(),
        }
    }

    /// Rebuild lookup indices after deserialization.
    pub fn rebuild_indices(&mut self) {
        self.id_to_index.clear();
        self.edge_id_to_index.clear();
        for idx in self.graph.node_indices() {
            let node = &self.graph[idx];
            self.id_to_index.insert(node.id.clone(), idx);
        }
        for idx in self.graph.edge_indices() {
            let edge = &self.graph[idx];
            self.edge_id_to_index.insert(edge.id.clone(), idx);
        }
    }

    pub fn add_node(
        &mut self,
        content: String,
        kind: NodeKind,
        metadata: HashMap<String, String>,
    ) -> &SpecNodeData {
        let id = Uuid::new_v4().to_string();
        let now = Utc::now().timestamp();
        let data = SpecNodeData {
            id: id.clone(),
            content,
            kind,
            metadata,
            created_at: now,
            modified_at: now,
            formality_layer: 0,  // Default to natural language
        };
        let idx = self.graph.add_node(data);
        self.id_to_index.insert(id, idx);
        &self.graph[idx]
    }

    /// Add a node from loaded data (preserves existing ID and timestamps)
    pub fn add_node_from_loaded(&mut self, node: SpecNodeData) -> String {
        let id = node.id.clone();
        let idx = self.graph.add_node(node);
        self.id_to_index.insert(id.clone(), idx);
        id
    }

    pub fn get_node(&self, id: &str) -> Option<&SpecNodeData> {
        self.id_to_index.get(id).map(|&idx| &self.graph[idx])
    }

    /// Find a node by content and kind (for deduplication)
    pub fn find_node_by_content(&self, content: &str, kind: NodeKind) -> Option<&SpecNodeData> {
        self.graph
            .node_weights()
            .find(|n| n.content == content && n.kind == kind)
    }

    pub fn update_node_formality(&mut self, id: &str, formality_layer: u8) -> bool {
        if let Some(&idx) = self.id_to_index.get(id) {
            if let Some(node) = self.graph.node_weight_mut(idx) {
                node.formality_layer = formality_layer;
                node.modified_at = Utc::now().timestamp();
                return true;
            }
        }
        false
    }

    pub fn update_node_metadata(&mut self, id: &str, key: String, value: String) -> Option<SpecNodeData> {
        if let Some(&idx) = self.id_to_index.get(id) {
            if let Some(node) = self.graph.node_weight_mut(idx) {
                node.metadata.insert(key, value);
                node.modified_at = Utc::now().timestamp();
                return Some(node.clone());
            }
        }
        None
    }

    pub fn remove_node(&mut self, id: &str) -> Option<SpecNodeData> {
        if let Some(&idx) = self.id_to_index.get(id) {
            // Remove related edge index entries
            let edge_indices: Vec<EdgeIndex> = self
                .graph
                .edges_directed(idx, Direction::Outgoing)
                .chain(self.graph.edges_directed(idx, Direction::Incoming))
                .map(|e| e.id())
                .collect();
            for eidx in edge_indices {
                if let Some(edge_data) = self.graph.edge_weight(eidx) {
                    self.edge_id_to_index.remove(&edge_data.id);
                }
            }

            let data = self.graph.remove_node(idx)?;
            self.id_to_index.remove(&data.id);

            // After removal petgraph may swap indices; rebuild to stay consistent.
            self.rebuild_indices();
            Some(data)
        } else {
            None
        }
    }

    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
        self.graph
            .node_weights()
            .filter(|n| kind_filter.is_none() || Some(n.kind) == kind_filter)
            .collect()
    }

    pub fn add_edge(
        &mut self,
        source_id: &str,
        target_id: &str,
        kind: EdgeKind,
        metadata: HashMap<String, String>,
    ) -> Result<&SpecEdgeData, GraphError> {
        let &src_idx = self
            .id_to_index
            .get(source_id)
            .ok_or_else(|| GraphError::NodeNotFound(source_id.to_string()))?;
        let &tgt_idx = self
            .id_to_index
            .get(target_id)
            .ok_or_else(|| GraphError::NodeNotFound(target_id.to_string()))?;

        let id = Uuid::new_v4().to_string();
        let now = Utc::now().timestamp();
        let data = SpecEdgeData {
            id: id.clone(),
            kind,
            metadata,
            created_at: now,
        };
        let eidx = self.graph.add_edge(src_idx, tgt_idx, data);
        self.edge_id_to_index.insert(id, eidx);
        Ok(&self.graph[eidx])
    }

    /// Add an edge from loaded data (preserves existing ID and timestamps)
    pub fn add_edge_from_loaded(&mut self, edge: Edge) -> Result<String, GraphError> {
        let &src_idx = self
            .id_to_index
            .get(&edge.source)
            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
        let &tgt_idx = self
            .id_to_index
            .get(&edge.target)
            .ok_or_else(|| GraphError::NodeNotFound(edge.target.clone()))?;

        let id = edge.data.id.clone();
        let eidx = self.graph.add_edge(src_idx, tgt_idx, edge.data);
        self.edge_id_to_index.insert(id.clone(), eidx);
        Ok(id)
    }

    pub fn remove_edge(&mut self, id: &str) -> Option<SpecEdgeData> {
        if let Some(&eidx) = self.edge_id_to_index.get(id) {
            let data = self.graph.remove_edge(eidx)?;
            self.edge_id_to_index.remove(&data.id);
            // Edge removal can invalidate other edge indices; rebuild.
            self.rebuild_indices();
            Some(data)
        } else {
            None
        }
    }

    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
        self.graph
            .edge_indices()
            .filter_map(|eidx| {
                let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
                let edge_data = &self.graph[eidx];
                let src_data = &self.graph[src_idx];
                let tgt_data = &self.graph[tgt_idx];
                if let Some(nid) = node_id {
                    if src_data.id != nid && tgt_data.id != nid {
                        return None;
                    }
                }
                Some((edge_data, src_data.id.as_str(), tgt_data.id.as_str()))
            })
            .collect()
    }

    pub fn node_count(&self) -> usize {
        self.graph.node_count()
    }

    pub fn edge_count(&self) -> usize {
        self.graph.edge_count()
    }

    /// Iterator over all nodes (for serialization)
    pub fn nodes(&self) -> impl Iterator<Item = &SpecNodeData> {
        self.graph.node_weights()
    }

    /// Iterator over all edges with source/target IDs (for serialization)
    pub fn edges(&self) -> impl Iterator<Item = Edge> + '_ {
        self.graph.edge_indices().filter_map(move |eidx| {
            let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
            let edge_data = self.graph[eidx].clone();
            let source = self.graph[src_idx].id.clone();
            let target = self.graph[tgt_idx].id.clone();
            Some(Edge {
                source,
                target,
                data: edge_data,
            })
        })
    }

    /// Detect contradictions: pairs of nodes explicitly connected by a Contradicts edge,
    /// plus structural contradictions (e.g., constraint vs scenario on the same domain
    /// that logically conflict).
    pub fn detect_contradictions(&self) -> Vec<Contradiction> {
        let mut result = Vec::new();

        // Explicit contradiction edges
        for eidx in self.graph.edge_indices() {
            let edge = &self.graph[eidx];
            if edge.kind == EdgeKind::Contradicts {
                if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
                    result.push(Contradiction {
                        node_a: self.graph[src_idx].clone(),
                        node_b: self.graph[tgt_idx].clone(),
                        explanation: format!(
                            "Explicit contradiction edge '{}'",
                            edge.id
                        ),
                    });
                }
            }
        }

        // Structural: nodes in the same domain with conflicting kinds
        // (Constraint + Scenario on same domain may indicate tension)
        let domains: Vec<(NodeIndex, &SpecNodeData)> = self
            .graph
            .node_indices()
            .map(|idx| (idx, &self.graph[idx]))
            .filter(|(_, n)| n.kind == NodeKind::Domain)
            .collect();

        for (domain_idx, _domain_data) in &domains {
            let children: Vec<(NodeIndex, &SpecNodeData)> = self
                .graph
                .edges_directed(*domain_idx, Direction::Incoming)
                .filter_map(|e| {
                    if self.graph[e.id()].kind == EdgeKind::Refines
                        || self.graph[e.id()].kind == EdgeKind::DependsOn
                    {
                        let src = e.source();
                        Some((src, &self.graph[src]))
                    } else {
                        None
                    }
                })
                .collect();

            let constraints: Vec<&SpecNodeData> = children
                .iter()
                .filter(|(_, n)| n.kind == NodeKind::Constraint)
                .map(|(_, n)| *n)
                .collect();
            let scenarios: Vec<&SpecNodeData> = children
                .iter()
                .filter(|(_, n)| n.kind == NodeKind::Scenario)
                .map(|(_, n)| *n)
                .collect();

            // Flag when constraints and scenarios coexist under the same domain —
            // this is a potential tension point that warrants review.
            if !constraints.is_empty() && !scenarios.is_empty() {
                for c in &constraints {
                    for s in &scenarios {
                        result.push(Contradiction {
                            node_a: (*c).clone(),
                            node_b: (*s).clone(),
                            explanation: format!(
                                "Potential tension: constraint and scenario under same domain"
                            ),
                        });
                    }
                }
            }
        }

        // Detect duplicates and semantic contradictions within same layer
        let all_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
            .graph
            .node_indices()
            .map(|idx| (idx, &self.graph[idx]))
            .filter(|(_, node)| {
                // Skip Definitions (meta-specifications, examples, test data)
                node.kind != NodeKind::Definition
            })
            .collect();

        for i in 0..all_nodes.len() {
            for j in (i + 1)..all_nodes.len() {
                let (idx_a, node_a) = all_nodes[i];
                let (idx_b, node_b) = all_nodes[j];

                // Skip if nodes are connected by Synonym edge (duplicates are intentional)
                let has_synonym_edge = self.graph.edges_connecting(idx_a, idx_b).any(|e| {
                    self.graph[e.id()].kind == EdgeKind::Synonym
                }) || self.graph.edges_connecting(idx_b, idx_a).any(|e| {
                    self.graph[e.id()].kind == EdgeKind::Synonym
                });
                if has_synonym_edge {
                    continue;
                }

                // Check for exact duplicates (same content and kind)
                if node_a.content.trim() == node_b.content.trim() && node_a.kind == node_b.kind {
                    result.push(Contradiction {
                        node_a: node_a.clone(),
                        node_b: node_b.clone(),
                        explanation: format!(
                            "Duplicate specification: same content and kind '{:?}'",
                            node_a.kind
                        ),
                    });
                    continue; // Skip semantic check if exact duplicate
                }

                // Check for semantic contradictions (e.g., password 8 vs 10 chars)
                // Only check within same formality layer to avoid false positives
                if node_a.formality_layer == node_b.formality_layer {
                    // Try Z3 formal verification first (provides mathematical certainty)
                    if let Some(explanation) = Self::detect_contradiction_via_z3(node_a, node_b) {
                        result.push(Contradiction {
                            node_a: node_a.clone(),
                            node_b: node_b.clone(),
                            explanation,
                        });
                        continue; // Z3 proof is conclusive, skip heuristic check
                    }

                    // Fallback to heuristic keyword matching if Z3 can't extract constraints
                    if let Some(explanation) = Self::detect_semantic_contradiction(
                        &node_a.content,
                        &node_b.content,
                    ) {
                        result.push(Contradiction {
                            node_a: node_a.clone(),
                            node_b: node_b.clone(),
                            explanation,
                        });
                    }
                }
            }
        }

        result
    }

    /// Detect omissions: nodes that have no edges (isolated), domains without
    /// any refinements, scenarios without supporting assertions.
    pub fn detect_omissions(&self) -> Vec<Omission> {
        let mut result = Vec::new();

        // Isolated nodes (no edges at all)
        for idx in self.graph.node_indices() {
            let incoming = self.graph.edges_directed(idx, Direction::Incoming).count();
            let outgoing = self.graph.edges_directed(idx, Direction::Outgoing).count();
            if incoming == 0 && outgoing == 0 {
                result.push(Omission {
                    description: "Isolated node with no relationships".to_string(),
                    related_nodes: vec![self.graph[idx].clone()],
                });
            }
        }

        // Domain nodes without any Refines edges pointing to them
        for idx in self.graph.node_indices() {
            let node = &self.graph[idx];
            if node.kind == NodeKind::Domain {
                let has_refinement = self
                    .graph
                    .edges_directed(idx, Direction::Incoming)
                    .any(|e| self.graph[e.id()].kind == EdgeKind::Refines);
                if !has_refinement {
                    result.push(Omission {
                        description: "Domain has no refinements".to_string(),
                        related_nodes: vec![node.clone()],
                    });
                }
            }
        }

        // Scenarios without supporting specifications (assertions or constraints)
        for idx in self.graph.node_indices() {
            let node = &self.graph[idx];
            if node.kind == NodeKind::Scenario {
                let has_support = self
                    .graph
                    .edges_directed(idx, Direction::Incoming)
                    .any(|e| {
                        let src = e.source();
                        matches!(self.graph[src].kind, NodeKind::Assertion | NodeKind::Constraint)
                    });
                let has_outgoing_support = self
                    .graph
                    .edges_directed(idx, Direction::Outgoing)
                    .any(|e| {
                        let tgt = e.target();
                        matches!(self.graph[tgt].kind, NodeKind::Assertion | NodeKind::Constraint)
                    });
                if !has_support && !has_outgoing_support {
                    result.push(Omission {
                        description: "Scenario has no supporting specifications".to_string(),
                        related_nodes: vec![node.clone()],
                    });
                }
            }
        }

        result
    }

    /// Search nodes by content substring (case-insensitive).
    pub fn search(&self, query: &str) -> Vec<&SpecNodeData> {
        let q = query.to_lowercase();
        self.graph
            .node_weights()
            .filter(|n| n.content.to_lowercase().contains(&q))
            .collect()
    }

    /// Find all synonym groups: nodes connected by Synonym edges.
    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
        let t = term.to_lowercase();

        // Find definition nodes matching the term
        let definitions: Vec<&SpecNodeData> = self
            .graph
            .node_weights()
            .filter(|n| n.kind == NodeKind::Definition && n.content.to_lowercase().contains(&t))
            .collect();

        // Collect synonyms via Synonym edges
        let mut synonyms = Vec::new();
        for def in &definitions {
            if let Some(&idx) = self.id_to_index.get(&def.id) {
                for edge in self
                    .graph
                    .edges_directed(idx, Direction::Outgoing)
                    .chain(self.graph.edges_directed(idx, Direction::Incoming))
                {
                    if self.graph[edge.id()].kind == EdgeKind::Synonym {
                        let other_idx = if edge.source() == idx {
                            edge.target()
                        } else {
                            edge.source()
                        };
                        let other = &self.graph[other_idx];
                        if !synonyms.contains(&other.content) {
                            synonyms.push(other.content.clone());
                        }
                    }
                }
            }
        }

        (definitions, synonyms)
    }

    /// Filter nodes by formality layer.
    pub fn filter_by_layer(&self, min_layer: u8, max_layer: u8) -> Vec<&SpecNodeData> {
        self.graph
            .node_weights()
            .filter(|n| n.formality_layer >= min_layer && n.formality_layer <= max_layer)
            .collect()
    }

    /// Detect cross-layer inconsistencies: nodes connected by Formalizes edges
    /// where the source has higher formality than target (should be reversed).
    pub fn detect_layer_inconsistencies(&self) -> Vec<LayerInconsistency> {
        let mut result = Vec::new();

        for eidx in self.graph.edge_indices() {
            let edge = &self.graph[eidx];
            if edge.kind == EdgeKind::Formalizes {
                if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
                    let src = &self.graph[src_idx];
                    let tgt = &self.graph[tgt_idx];

                    // Formalizes should go from lower to higher formality
                    if src.formality_layer >= tgt.formality_layer {
                        result.push(LayerInconsistency {
                            source: src.clone(),
                            target: tgt.clone(),
                            explanation: format!(
                                "Formalizes edge goes from layer {} to layer {} (should increase)",
                                src.formality_layer, tgt.formality_layer
                            ),
                        });
                    }
                }
            }
        }

        result
    }

    /// Detect inter-universe inconsistencies: specifications across different universes
    /// (U₁, U₂, ...) that contradict each other despite Transform edges connecting them.
    /// This addresses the conversation.md critique about multi-layered specifications.
    pub fn detect_inter_universe_inconsistencies(&self) -> Vec<InterUniverseInconsistency> {
        let mut result = Vec::new();

        // Group nodes by universe (from metadata "universe" field)
        let mut universe_nodes: HashMap<String, Vec<(NodeIndex, &SpecNodeData)>> = HashMap::new();
        for idx in self.graph.node_indices() {
            let node = &self.graph[idx];
            if let Some(universe) = node.metadata.get("universe") {
                universe_nodes
                    .entry(universe.clone())
                    .or_insert_with(Vec::new)
                    .push((idx, node));
            }
        }

        // For each Transform edge, check if the specifications are consistent
        for eidx in self.graph.edge_indices() {
            let edge = &self.graph[eidx];
            if edge.kind == EdgeKind::Transform {
                if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
                    let src_node = &self.graph[src_idx];
                    let tgt_node = &self.graph[tgt_idx];

                    let src_universe = src_node.metadata.get("universe").map(|s| s.as_str());
                    let tgt_universe = tgt_node.metadata.get("universe").map(|s| s.as_str());

                    // Only check if both nodes have universe metadata and they differ
                    if let (Some(u_a), Some(u_b)) = (src_universe, tgt_universe) {
                        if u_a != u_b {
                            // Check for semantic contradiction via simple heuristics:
                            // 1. Contradictory keywords (must/must not, required/forbidden)
                            // 2. Conflicting numeric constraints
                            let contradiction = Self::detect_semantic_contradiction(
                                &src_node.content,
                                &tgt_node.content,
                            );

                            if let Some(explanation) = contradiction {
                                result.push(InterUniverseInconsistency {
                                    universe_a: u_a.to_string(),
                                    universe_b: u_b.to_string(),
                                    spec_a: src_node.clone(),
                                    spec_b: tgt_node.clone(),
                                    transform_path: vec![edge.id.clone()],
                                    explanation,
                                });
                            }
                        }
                    }
                }
            }
        }

        // Check for contradictions across universes without direct Transform edges
        // (this catches missing transformation functions - the "f" gap)
        let universe_names: Vec<String> = universe_nodes.keys().cloned().collect();
        for i in 0..universe_names.len() {
            for j in (i + 1)..universe_names.len() {
                let u_a = &universe_names[i];
                let u_b = &universe_names[j];

                if let (Some(nodes_a), Some(nodes_b)) =
                    (universe_nodes.get(u_a), universe_nodes.get(u_b))
                {
                    // Check if there's a Transform path between these universes
                    let has_transform = self.graph.edge_indices().any(|eidx| {
                        let edge = &self.graph[eidx];
                        if edge.kind != EdgeKind::Transform {
                            return false;
                        }
                        if let Some((src_idx, tgt_idx)) = self.graph.edge_endpoints(eidx) {
                            let src_u = self.graph[src_idx].metadata.get("universe");
                            let tgt_u = self.graph[tgt_idx].metadata.get("universe");
                            (src_u.map(|s| s.as_str()) == Some(u_a.as_str())
                                && tgt_u.map(|s| s.as_str()) == Some(u_b.as_str()))
                                || (src_u.map(|s| s.as_str()) == Some(u_b.as_str())
                                    && tgt_u.map(|s| s.as_str()) == Some(u_a.as_str()))
                        } else {
                            false
                        }
                    });

                    // If no transform exists but both universes have related concepts, flag it
                    if !has_transform {
                        for (_, node_a) in nodes_a {
                            for (_, node_b) in nodes_b {
                                // Check if concepts are related (similar content)
                                if Self::are_related_concepts(&node_a.content, &node_b.content) {
                                    result.push(InterUniverseInconsistency {
                                        universe_a: u_a.clone(),
                                        universe_b: u_b.clone(),
                                        spec_a: (*node_a).clone(),
                                        spec_b: (*node_b).clone(),
                                        transform_path: vec![],
                                        explanation: format!(
                                            "Missing transformation function (f) between universes '{}' and '{}' for related concepts",
                                            u_a, u_b
                                        ),
                                    });
                                }
                            }
                        }
                    }
                }
            }
        }

        result
    }

    /// Helper: detect semantic contradiction between two specification strings
    fn detect_semantic_contradiction(content_a: &str, content_b: &str) -> Option<String> {
        let a_lower = content_a.to_lowercase();
        let b_lower = content_b.to_lowercase();

        // Check for must/must not conflicts (only if concepts are related)
        // Exclude specs that have both "must" and "must not" within the same text
        // (e.g., "must maintain idempotency: ... must not create duplicates" - not contradictory)
        let a_has_must = a_lower.contains("must") && !a_lower.contains("must not");
        let b_has_must_not = b_lower.contains("must not") || b_lower.contains("forbidden");
        let a_has_both = a_lower.contains("must") && a_lower.contains("must not");
        let b_has_both = b_lower.contains("must") && b_lower.contains("must not");

        if a_has_must
            && b_has_must_not
            && !a_has_both  // Exclude if A has both "must" and "must not"
            && !b_has_both  // Exclude if B has both "must" and "must not"
            && Self::are_related_concepts(content_a, content_b)
        {
            return Some("Contradictory requirement: 'must' vs 'must not'".to_string());
        }

        // Check for required/optional conflicts (only if concepts are related)
        if a_lower.contains("required") && b_lower.contains("optional")
            && Self::are_related_concepts(content_a, content_b)
        {
            return Some("Contradictory requirement: 'required' vs 'optional'".to_string());
        }

        // Extract and compare numeric constraints
        if let (Some(num_a), Some(num_b)) = (Self::extract_minimum_value(&a_lower), Self::extract_minimum_value(&b_lower)) {
            if num_a != num_b && a_lower.contains("password") && b_lower.contains("password") {
                return Some(format!("Conflicting password length: {} vs {} characters", num_a, num_b));
            }
            if num_a != num_b && Self::are_related_concepts(content_a, content_b)
                && (a_lower.contains("length") || b_lower.contains("length")
                || a_lower.contains("minimum") || b_lower.contains("minimum")
                || a_lower.contains("at least") || b_lower.contains("at least")) {
                return Some(format!("Conflicting minimum values: {} vs {}", num_a, num_b));
            }
        }

        // Check for conflicting numeric constraints (only if about same variable)
        if a_lower.contains(">=") && b_lower.contains("<")
            && Self::are_related_concepts(content_a, content_b)
        {
            return Some("Potentially conflicting numeric constraints".to_string());
        }

        None
    }

    /// Extract minimum value from phrases like "at least 8", "minimum 10", ">= 5", etc.
    fn extract_minimum_value(text: &str) -> Option<u32> {
        // Try to find patterns like "at least N", "minimum N", ">= N", "min N", "minimum of N"
        use regex::Regex;
        let patterns = [
            r"at least (\d+)",
            r"minimum (\d+)",
            r"min (\d+)",
            r"minimum of (\d+)",
            r">= ?(\d+)",
            r"≥ ?(\d+)",
        ];

        for pattern in &patterns {
            if let Ok(re) = Regex::new(pattern) {
                if let Some(cap) = re.captures(text) {
                    if let Some(num_str) = cap.get(1) {
                        if let Ok(num) = num_str.as_str().parse::<u32>() {
                            return Some(num);
                        }
                    }
                }
            }
        }

        None
    }

    /// Extract maximum value from phrases like "at most 10", "maximum 20", "<= 15", etc.
    fn extract_maximum_value(text: &str) -> Option<u32> {
        // Try to find patterns like "at most N", "maximum N", "<= N", "max N", "maximum of N"
        use regex::Regex;
        let patterns = [
            r"at most (\d+)",
            r"maximum (\d+)",
            r"max (\d+)",
            r"maximum of (\d+)",
            r"<= ?(\d+)",
            r"≤ ?(\d+)",
        ];

        for pattern in &patterns {
            if let Ok(re) = Regex::new(pattern) {
                if let Some(cap) = re.captures(text) {
                    if let Some(num_str) = cap.get(1) {
                        if let Ok(num) = num_str.as_str().parse::<u32>() {
                            return Some(num);
                        }
                    }
                }
            }
        }

        None
    }

    /// Helper: check if two concepts are related (share significant terms or word stems)
    fn are_related_concepts(content_a: &str, content_b: &str) -> bool {
        let a_lower = content_a.to_lowercase();
        let b_lower = content_b.to_lowercase();

        // Filter out meta-words that don't indicate semantic relatedness
        let meta_words = ["invariant", "template", "contains", "fetched", "expected"];

        let a_words: Vec<&str> = a_lower
            .split(|c: char| !c.is_alphanumeric())
            .filter(|w| w.len() > 4 && !meta_words.contains(w)) // Only significant words, exclude meta-words
            .collect();
        let b_words: Vec<&str> = b_lower
            .split(|c: char| !c.is_alphanumeric())
            .filter(|w| w.len() > 4 && !meta_words.contains(w))
            .collect();

        // Check for exact word matches
        let exact_matches = a_words.iter().filter(|w| b_words.contains(w)).count();
        if exact_matches >= 2 {
            return true;
        }

        // Check for word stems (common prefix of at least 5 chars)
        let mut stem_matches = 0;
        for &word_a in &a_words {
            for &word_b in &b_words {
                let min_len = word_a.len().min(word_b.len());
                if min_len >= 5 {
                    let prefix_len = word_a
                        .chars()
                        .zip(word_b.chars())
                        .take_while(|(a, b)| a == b)
                        .count();
                    if prefix_len >= 5 {
                        stem_matches += 1;
                        break; // Count each word_a only once
                    }
                }
            }
        }

        exact_matches >= 1 || stem_matches >= 1
    }

    /// Extract simple constraints from specification content for Z3 verification
    ///
    /// This is a pattern-based extractor for common constraint patterns.
    /// Not complete, but sufficient for basic formal verification.
    fn extract_constraints_from_content(content: &str) -> Vec<Constraint> {
        let mut constraints = Vec::new();
        let content_lower = content.to_lowercase();

        // Pattern: "must be at least N" / "minimum N" / ">= N"
        if let Some(min_val) = Self::extract_minimum_value(&content_lower) {
            if content_lower.contains("password") && (content_lower.contains("character") || content_lower.contains("length")) {
                let mut metadata_map = HashMap::new();
                metadata_map.insert("variable".to_string(), "password_length".to_string());
                metadata_map.insert("operator".to_string(), ">=".to_string());
                metadata_map.insert("value".to_string(), min_val.to_string());

                constraints.push(Constraint {
                    description: format!("Password must be at least {} characters", min_val),
                    formal: Some(format!("(>= password_length {})", min_val)),
                    kind: ConstraintKind::Universal,
                    metadata: crate::ConstraintMetadata::from(metadata_map),
                });
            } else if content_lower.contains("length") || content_lower.contains("minimum") {
                // Generic numeric constraint
                let mut metadata_map = HashMap::new();
                metadata_map.insert("operator".to_string(), ">=".to_string());
                metadata_map.insert("value".to_string(), min_val.to_string());

                constraints.push(Constraint {
                    description: format!("Value must be at least {}", min_val),
                    formal: Some(format!("(>= value {})", min_val)),
                    kind: ConstraintKind::Universal,
                    metadata: crate::ConstraintMetadata::from(metadata_map),
                });
            }
        }

        // Pattern: "must be at most N" / "maximum N" / "<= N"
        if let Some(max_val) = Self::extract_maximum_value(&content_lower) {
            if content_lower.contains("password") && (content_lower.contains("character") || content_lower.contains("length")) {
                let mut metadata_map = HashMap::new();
                metadata_map.insert("variable".to_string(), "password_length".to_string());
                metadata_map.insert("operator".to_string(), "<=".to_string());
                metadata_map.insert("value".to_string(), max_val.to_string());

                constraints.push(Constraint {
                    description: format!("Password must be at most {} characters", max_val),
                    formal: Some(format!("(<= password_length {})", max_val)),
                    kind: ConstraintKind::Universal,
                    metadata: crate::ConstraintMetadata::from(metadata_map),
                });
            } else if content_lower.contains("length") || content_lower.contains("maximum") {
                // Generic numeric constraint
                let mut metadata_map = HashMap::new();
                metadata_map.insert("operator".to_string(), "<=".to_string());
                metadata_map.insert("value".to_string(), max_val.to_string());

                constraints.push(Constraint {
                    description: format!("Value must be at most {}", max_val),
                    formal: Some(format!("(<= value {})", max_val)),
                    kind: ConstraintKind::Universal,
                    metadata: crate::ConstraintMetadata::from(metadata_map),
                });
            }
        }

        // Pattern: "must" / "required" (universal constraint)
        if content_lower.contains("must") && !content_lower.contains("must not") {
            let mut metadata_map = HashMap::new();
            metadata_map.insert("type".to_string(), "universal".to_string());
            constraints.push(Constraint {
                description: content.to_string(),
                formal: None, // Natural language only
                kind: ConstraintKind::Universal,
                metadata: crate::ConstraintMetadata::from(metadata_map),
            });
        }

        // Pattern: "must not" / "forbidden" (universal prohibition)
        if content_lower.contains("must not") || content_lower.contains("forbidden") {
            let mut metadata_map = HashMap::new();
            metadata_map.insert("type".to_string(), "prohibition".to_string());
            constraints.push(Constraint {
                description: content.to_string(),
                formal: None, // Natural language only
                kind: ConstraintKind::Universal,
                metadata: crate::ConstraintMetadata::from(metadata_map),
            });
        }

        constraints
    }

    /// Detect contradiction using Z3 SMT solver (formal verification)
    ///
    /// This provides mathematical certainty about contradictions, replacing
    /// heuristic keyword matching with formal proof.
    ///
    /// Returns Some(explanation) if contradiction is formally proven, None otherwise.
    fn detect_contradiction_via_z3(node_a: &SpecNodeData, node_b: &SpecNodeData) -> Option<String> {
        // Extract constraints from both nodes
        let constraints_a = Self::extract_constraints_from_content(&node_a.content);
        let constraints_b = Self::extract_constraints_from_content(&node_b.content);

        // If we can't extract formal constraints, return None (fallback to heuristics)
        if constraints_a.is_empty() || constraints_b.is_empty() {
            return None;
        }

        // Check if constraints mention the same variable/domain
        // We need to clone metadata access since we'll move constraints later
        let vars_a: std::collections::HashSet<_> = constraints_a
            .iter()
            .filter_map(|c| c.metadata.get_str("variable").map(|s| s.to_string()))
            .collect();
        let vars_b: std::collections::HashSet<_> = constraints_b
            .iter()
            .filter_map(|c| c.metadata.get_str("variable").map(|s| s.to_string()))
            .collect();

        let common_vars: Vec<String> = vars_a.intersection(&vars_b).cloned().collect();
        if common_vars.is_empty() {
            // No common variables, can't prove contradiction
            return None;
        }

        // Create admissible sets
        let mut set_a = AdmissibleSet::new(
            node_a.id.clone(),
            format!("U{}", node_a.formality_layer),
        );
        let mut set_b = AdmissibleSet::new(
            node_b.id.clone(),
            format!("U{}", node_b.formality_layer),
        );

        // Now we can move constraints into admissible sets
        for c in constraints_a {
            set_a.add_constraint(c);
        }
        for c in constraints_b {
            set_b.add_constraint(c);
        }

        // Call Z3-based Prover
        let mut prover = Prover::new();
        let proof = prover.prove_consistency(&set_a, &set_b);

        match proof.status {
            ProofStatus::Refuted => {
                // Contradiction formally proven by Z3
                let vars_list = common_vars.join(", ");
                Some(format!(
                    "Z3-verified contradiction on variable(s): {} (formally proven inconsistent)",
                    vars_list
                ))
            }
            ProofStatus::Proven => {
                // Formally proven consistent (no contradiction)
                None
            }
            ProofStatus::Unknown | ProofStatus::Pending => {
                // Can't prove or refute, fallback to heuristics
                None
            }
        }
    }

    /// Find all formalizations of a given node (nodes it formalizes to).
    pub fn find_formalizations(&self, node_id: &str) -> Vec<&SpecNodeData> {
        if let Some(&idx) = self.id_to_index.get(node_id) {
            self.graph
                .edges_directed(idx, Direction::Outgoing)
                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
                .map(|e| &self.graph[e.target()])
                .collect()
        } else {
            Vec::new()
        }
    }

    /// Find the natural language source for a formalized node (reverse of formalizations).
    pub fn find_natural_source(&self, node_id: &str) -> Vec<&SpecNodeData> {
        if let Some(&idx) = self.id_to_index.get(node_id) {
            self.graph
                .edges_directed(idx, Direction::Incoming)
                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
                .map(|e| &self.graph[e.source()])
                .collect()
        } else {
            Vec::new()
        }
    }

    /// Trace all relationships for a node, returning a hierarchical structure.
    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
    pub fn trace_relationships(&self, node_id: &str, max_depth: usize) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
        let mut result = Vec::new();
        let mut visited = std::collections::HashSet::new();

        if let Some(&start_idx) = self.id_to_index.get(node_id) {
            visited.insert(start_idx);
            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
        }

        result
    }

    fn trace_recursive(
        &self,
        idx: NodeIndex,
        max_depth: usize,
        current_depth: usize,
        visited: &mut std::collections::HashSet<NodeIndex>,
        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
    ) {
        if max_depth > 0 && current_depth >= max_depth {
            return;
        }

        // Traverse outgoing edges
        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
            let target_idx = edge.target();
            let edge_data = &self.graph[edge.id()];
            let target_node = &self.graph[target_idx];

            result.push((
                target_node.clone(),
                edge_data.kind,
                "outgoing".to_string(),
                current_depth + 1,
            ));

            if !visited.contains(&target_idx) {
                visited.insert(target_idx);
                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
            }
        }

        // Traverse incoming edges
        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
            let source_idx = edge.source();
            let edge_data = &self.graph[edge.id()];
            let source_node = &self.graph[source_idx];

            result.push((
                source_node.clone(),
                edge_data.kind,
                "incoming".to_string(),
                current_depth + 1,
            ));

            if !visited.contains(&source_idx) {
                visited.insert(source_idx);
                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
            }
        }
    }

    /// Find potentially related terms based on co-occurrence in metadata or content.
    /// This provides a lightweight semantic clustering without requiring external AI.
    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
        let t = term.to_lowercase();
        let mut scored_nodes: Vec<(&SpecNodeData, f32)> = Vec::new();

        // Find nodes that mention the term
        let mentioning_nodes: Vec<&SpecNodeData> = self
            .graph
            .node_weights()
            .filter(|n| n.content.to_lowercase().contains(&t))
            .collect();

        if mentioning_nodes.is_empty() {
            return scored_nodes;
        }

        // Extract significant words from mentioning nodes (excluding common words)
        let stop_words = ["the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for"];
        let mut term_context: std::collections::HashSet<String> = std::collections::HashSet::new();

        for node in &mentioning_nodes {
            for word in node.content.to_lowercase().split_whitespace() {
                let clean_word = word.trim_matches(|c: char| !c.is_alphanumeric());
                if clean_word.len() > 2 && !stop_words.contains(&clean_word) {
                    term_context.insert(clean_word.to_string());
                }
            }
        }

        // Score all nodes based on context overlap
        for node in self.graph.node_weights() {
            if mentioning_nodes.contains(&node) {
                continue; // Skip nodes that directly mention the term
            }

            let node_words: std::collections::HashSet<String> = node
                .content
                .to_lowercase()
                .split_whitespace()
                .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
                .filter(|w| w.len() > 2 && !stop_words.contains(&w.as_str()))
                .collect();

            let overlap = term_context.intersection(&node_words).count();
            if overlap > 0 {
                let score = overlap as f32 / term_context.len().max(1) as f32;
                scored_nodes.push((node, score));
            }
        }

        // Sort by score descending
        scored_nodes.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        scored_nodes
    }

    /// Detect potential synonym pairs based on graph structure.
    /// Nodes that share similar connections might be semantically related.
    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
        let mut candidates = Vec::new();
        let definition_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
            .graph
            .node_indices()
            .map(|idx| (idx, &self.graph[idx]))
            .filter(|(_, n)| n.kind == NodeKind::Definition)
            .collect();

        for i in 0..definition_nodes.len() {
            for j in (i + 1)..definition_nodes.len() {
                let (idx_a, node_a) = definition_nodes[i];
                let (idx_b, node_b) = definition_nodes[j];

                // Skip if already marked as synonyms
                let already_synonyms = self
                    .graph
                    .edges_directed(idx_a, Direction::Outgoing)
                    .chain(self.graph.edges_directed(idx_a, Direction::Incoming))
                    .any(|e| {
                        self.graph[e.id()].kind == EdgeKind::Synonym
                            && (e.source() == idx_b || e.target() == idx_b)
                    });

                if already_synonyms {
                    continue;
                }

                // Calculate structural similarity (Jaccard similarity of neighbors)
                let neighbors_a: std::collections::HashSet<NodeIndex> = self
                    .graph
                    .neighbors_undirected(idx_a)
                    .collect();
                let neighbors_b: std::collections::HashSet<NodeIndex> = self
                    .graph
                    .neighbors_undirected(idx_b)
                    .collect();

                if neighbors_a.is_empty() && neighbors_b.is_empty() {
                    continue;
                }

                let intersection = neighbors_a.intersection(&neighbors_b).count();
                let union = neighbors_a.union(&neighbors_b).count();

                if union > 0 {
                    let similarity = intersection as f32 / union as f32;
                    if similarity > 0.3 {
                        // Threshold for potential synonyms
                        candidates.push((node_a.clone(), node_b.clone(), similarity));
                    }
                }
            }
        }

        candidates.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
        candidates
    }

    /// Generate contract template from a specification node.
    /// For constraints: generates property-based test template
    /// For scenarios: generates unit test template
    pub fn generate_contract_template(&self, node_id: &str, language: &str) -> Option<String> {
        let node = self.get_node(node_id)?;

        match node.kind {
            NodeKind::Constraint => Some(self.generate_property_test(node, language)),
            NodeKind::Scenario => Some(self.generate_unit_test(node, language)),
            _ => None,
        }
    }

    fn generate_property_test(&self, node: &SpecNodeData, language: &str) -> String {
        match language {
            "rust" => format!(
                r#"#[quickcheck]
fn property_{}(input: /* TODO: define input type */) -> bool {{
    // Specification: {}
    // TODO: Implement property check
    todo!("Verify: {}")
}}
"#,
                node.id.replace('-', "_"),
                node.content,
                node.content
            ),
            "python" => format!(
                r#"@given(st./* TODO: define strategy */)
def test_property_{}(input):
    """Specification: {}"""
    # TODO: Implement property check
    assert False, "TODO: Verify {}"
"#,
                node.id.replace('-', "_"),
                node.content,
                node.content
            ),
            _ => format!(
                "// Property test for: {}\n// TODO: Implement in {}\n",
                node.content, language
            ),
        }
    }

    fn generate_unit_test(&self, node: &SpecNodeData, language: &str) -> String {
        match language {
            "rust" => format!(
                r#"#[test]
fn test_scenario_{}() {{
    // Scenario: {}
    // TODO: Implement test steps
    todo!("Test: {}")
}}
"#,
                node.id.replace('-', "_"),
                node.content,
                node.content
            ),
            "python" => format!(
                r#"def test_scenario_{}():
    """Scenario: {}"""
    # TODO: Implement test steps
    assert False, "TODO: Test {}"
"#,
                node.id.replace('-', "_"),
                node.content,
                node.content
            ),
            _ => format!(
                "// Unit test for: {}\n// TODO: Implement in {}\n",
                node.content, language
            ),
        }
    }

    /// Get test coverage report: which specifications have test links.
    pub fn get_test_coverage(&self) -> TestCoverage {
        let total_testable = self
            .graph
            .node_weights()
            .filter(|n| matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario))
            .count();

        let with_tests = self
            .graph
            .node_weights()
            .filter(|n| {
                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
                    && n.metadata.contains_key("test_file")
            })
            .count();

        let nodes_with_tests: Vec<SpecNodeData> = self
            .graph
            .node_weights()
            .filter(|n| {
                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
                    && n.metadata.contains_key("test_file")
            })
            .cloned()
            .collect();

        let nodes_without_tests: Vec<SpecNodeData> = self
            .graph
            .node_weights()
            .filter(|n| {
                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
                    && !n.metadata.contains_key("test_file")
            })
            .cloned()
            .collect();

        TestCoverage {
            total_testable,
            with_tests,
            coverage_ratio: if total_testable > 0 {
                with_tests as f32 / total_testable as f32
            } else {
                0.0
            },
            nodes_with_tests,
            nodes_without_tests,
        }
    }

    /// Calculate compliance score between a specification and code snippet.
    /// Returns score 0.0-1.0 based on semantic similarity.
    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
        let node = self.get_node(node_id)?;

        // Extract keywords from specification
        let spec_keywords = self.extract_keywords(&node.content);
        let code_keywords = self.extract_keywords(code);

        if spec_keywords.is_empty() {
            return Some(ComplianceScore {
                score: 0.0,
                keyword_overlap: 0.0,
                structural_match: 0.0,
                explanation: "Specification has no extractable keywords".to_string(),
            });
        }

        // Calculate keyword overlap (Jaccard similarity)
        let intersection = spec_keywords.intersection(&code_keywords).count();
        let union = spec_keywords.union(&code_keywords).count();
        let keyword_overlap = if union > 0 {
            intersection as f32 / union as f32
        } else {
            0.0
        };

        // Structural matching for constraints/scenarios
        let structural_match = match node.kind {
            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
            _ => 0.5, // Neutral for other types
        };

        // Weighted average (60% keywords, 40% structure)
        let score = keyword_overlap * 0.6 + structural_match * 0.4;

        let explanation = if score > 0.8 {
            "Strong compliance - code closely matches specification".to_string()
        } else if score > 0.5 {
            "Moderate compliance - code partially matches specification".to_string()
        } else if score > 0.2 {
            "Weak compliance - code loosely relates to specification".to_string()
        } else {
            "Poor compliance - code does not match specification".to_string()
        };

        Some(ComplianceScore {
            score,
            keyword_overlap,
            structural_match,
            explanation,
        })
    }

    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
        let stop_words = [
            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
            "is", "are", "was", "were", "be", "been", "being", "have", "has", "had",
            "do", "does", "did", "will", "would", "should", "could", "may", "might",
            "must", "can", "of", "by", "with", "from", "as", "into", "through"
        ];

        text.to_lowercase()
            .split_whitespace()
            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
            .filter(|w| w.len() > 2 && !stop_words.contains(w))
            .map(|w| w.to_string())
            .collect()
    }

    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
        let spec_lower = spec.to_lowercase();
        let code_lower = code.to_lowercase();

        let mut score: f32 = 0.0;

        // Look for constraint patterns
        if (spec_lower.contains("must") || spec_lower.contains("should"))
            && (code_lower.contains("assert") || code_lower.contains("require")
                || code_lower.contains("invariant"))
        {
            score += 0.3;
        }

        // Look for comparison operators
        if (spec_lower.contains('>') || spec_lower.contains('<') || spec_lower.contains("greater")
            || spec_lower.contains("less"))
            && (code_lower.contains('>') || code_lower.contains('<'))
        {
            score += 0.2;
        }

        // Look for equality checks
        if (spec_lower.contains("equal") || spec_lower.contains("same"))
            && (code_lower.contains("==") || code_lower.contains("equals"))
        {
            score += 0.2;
        }

        // Look for boundary conditions
        if (spec_lower.contains("not") || spec_lower.contains("never"))
            && (code_lower.contains('!') || code_lower.contains("not"))
        {
            score += 0.3;
        }

        score.min(1.0)
    }

    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
        let spec_lower = spec.to_lowercase();
        let code_lower = code.to_lowercase();

        let mut score: f32 = 0.0;

        // Look for action words
        let action_words = ["login", "create", "update", "delete", "send", "receive", "verify"];
        let has_action = action_words.iter().any(|&w| spec_lower.contains(w) && code_lower.contains(w));
        if has_action {
            score += 0.4;
        }

        // Look for test structure
        if code_lower.contains("test") || code_lower.contains("scenario") {
            score += 0.2;
        }

        // Look for setup/action/verify pattern
        let has_setup = code_lower.contains("setup") || code_lower.contains("given");
        let has_action_code = code_lower.contains("when") || code_lower.contains("act");
        let has_verify = code_lower.contains("assert") || code_lower.contains("verify")
            || code_lower.contains("expect");

        if has_setup { score += 0.1; }
        if has_action_code { score += 0.15; }
        if has_verify { score += 0.15; }

        score.min(1.0)
    }

    /// Get compliance report for all specifications with linked code.
    pub fn get_compliance_report(&self) -> Vec<(SpecNodeData, ComplianceScore)> {
        self.graph
            .node_weights()
            .filter(|n| n.metadata.contains_key("impl_code") || n.metadata.contains_key("test_code"))
            .filter_map(|n| {
                let code = n.metadata.get("impl_code")
                    .or_else(|| n.metadata.get("test_code"))?;
                let score = self.calculate_compliance(&n.id, code)?;
                Some((n.clone(), score))
            })
            .collect()
    }

    /// Query graph state at a specific timestamp.
    /// Returns nodes and edges that existed at that time.
    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
        let nodes: Vec<SpecNodeData> = self
            .graph
            .node_weights()
            .filter(|n| n.created_at <= timestamp)
            .cloned()
            .collect();

        let edges: Vec<SpecEdgeData> = self
            .graph
            .edge_indices()
            .filter_map(|eidx| {
                let edge = &self.graph[eidx];
                if edge.created_at <= timestamp {
                    Some(edge.clone())
                } else {
                    None
                }
            })
            .collect();

        let node_count = nodes.len();
        let edge_count = edges.len();

        TemporalSnapshot {
            timestamp,
            nodes,
            edges,
            node_count,
            edge_count,
        }
    }

    /// Diff graph state between two timestamps.
    /// Shows what was added, modified, or removed.
    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
        let from_snapshot = self.query_at_timestamp(from_timestamp);
        let to_snapshot = self.query_at_timestamp(to_timestamp);

        let from_node_ids: std::collections::HashSet<String> =
            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
        let to_node_ids: std::collections::HashSet<String> =
            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();

        let added_nodes: Vec<SpecNodeData> = to_snapshot
            .nodes
            .iter()
            .filter(|n| !from_node_ids.contains(&n.id))
            .cloned()
            .collect();

        let removed_nodes: Vec<SpecNodeData> = from_snapshot
            .nodes
            .iter()
            .filter(|n| !to_node_ids.contains(&n.id))
            .cloned()
            .collect();

        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
            .nodes
            .iter()
            .filter_map(|to_node| {
                from_snapshot
                    .nodes
                    .iter()
                    .find(|from_node| from_node.id == to_node.id)
                    .and_then(|from_node| {
                        if from_node.modified_at < to_node.modified_at {
                            Some((from_node.clone(), to_node.clone()))
                        } else {
                            None
                        }
                    })
            })
            .collect();

        let from_edge_ids: std::collections::HashSet<String> =
            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
        let to_edge_ids: std::collections::HashSet<String> =
            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();

        let added_edges: Vec<SpecEdgeData> = to_snapshot
            .edges
            .iter()
            .filter(|e| !from_edge_ids.contains(&e.id))
            .cloned()
            .collect();

        let removed_edges: Vec<SpecEdgeData> = from_snapshot
            .edges
            .iter()
            .filter(|e| !to_edge_ids.contains(&e.id))
            .cloned()
            .collect();

        TemporalDiff {
            from_timestamp,
            to_timestamp,
            added_nodes,
            removed_nodes,
            modified_nodes,
            added_edges,
            removed_edges,
        }
    }

    /// Get evolution history of a specific node.
    /// Returns timeline of changes to the node.
    pub fn get_node_history(&self, node_id: &str) -> Option<NodeHistory> {
        let node = self.get_node(node_id)?;

        let mut events = Vec::new();

        // Creation event
        events.push(HistoryEvent {
            timestamp: node.created_at,
            event_type: "created".to_string(),
            description: format!("Node created: {}", node.content),
        });

        // Modification event (if modified after creation)
        if node.modified_at > node.created_at {
            events.push(HistoryEvent {
                timestamp: node.modified_at,
                event_type: "modified".to_string(),
                description: "Node content or metadata modified".to_string(),
            });
        }

        // Edge creation events
        if let Some(&idx) = self.id_to_index.get(node_id) {
            for edge in self
                .graph
                .edges_directed(idx, Direction::Outgoing)
                .chain(self.graph.edges_directed(idx, Direction::Incoming))
            {
                let edge_data = &self.graph[edge.id()];
                events.push(HistoryEvent {
                    timestamp: edge_data.created_at,
                    event_type: "edge_added".to_string(),
                    description: format!("Edge added: {:?}", edge_data.kind),
                });
            }
        }

        // Sort events by timestamp
        events.sort_by_key(|e| e.timestamp);

        Some(NodeHistory {
            node: node.clone(),
            events,
        })
    }

    /// Track compliance trend over time for nodes with historical compliance data.
    /// Requires compliance scores stored in metadata with timestamps.
    pub fn get_compliance_trend(&self, node_id: &str) -> Option<ComplianceTrend> {
        let node = self.get_node(node_id)?;

        // Extract compliance history from metadata (format: "compliance_<timestamp>")
        let mut data_points: Vec<ComplianceDataPoint> = node
            .metadata
            .iter()
            .filter_map(|(key, value)| {
                if key.starts_with("compliance_") {
                    let timestamp_str = key.strip_prefix("compliance_")?;
                    let timestamp: i64 = timestamp_str.parse().ok()?;
                    let score: f32 = value.parse().ok()?;
                    Some(ComplianceDataPoint { timestamp, score })
                } else {
                    None
                }
            })
            .collect();

        if data_points.is_empty() {
            return None;
        }

        // Sort by timestamp
        data_points.sort_by_key(|d| d.timestamp);

        let trend_direction = if data_points.len() >= 2 {
            let first = data_points[0].score;
            let last = data_points[data_points.len() - 1].score;
            if last > first + 0.1 {
                "improving".to_string()
            } else if last < first - 0.1 {
                "degrading".to_string()
            } else {
                "stable".to_string()
            }
        } else {
            "unknown".to_string()
        };

        Some(ComplianceTrend {
            node: node.clone(),
            data_points,
            trend_direction,
        })
    }

    /// Export the specification graph in DOT format (Graphviz).
    /// Nodes are colored by formality layer (U0=blue, U1=green, U2=yellow, U3=red).
    /// Edges are styled by kind (Refines, Formalizes, etc.).
    pub fn export_dot(&self) -> String {
        let mut dot = String::from("digraph spec_oracle {\n");
        dot.push_str("    rankdir=LR;\n");
        dot.push_str("    node [shape=box, style=filled];\n");
        dot.push_str("    edge [fontsize=10];\n\n");

        // Helper function to escape DOT strings
        fn escape_dot(s: &str) -> String {
            s.replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('\n', "\\n")
        }

        // Helper function to truncate content
        fn truncate(s: &str, max_len: usize) -> String {
            if s.len() > max_len {
                format!("{}...", &s[..max_len])
            } else {
                s.to_string()
            }
        }

        // Helper function to get layer color
        fn layer_color(layer: u8) -> &'static str {
            match layer {
                0 => "lightblue",   // U0: natural language
                1 => "lightgreen",  // U1: structured/formal
                2 => "lightyellow", // U2: interface/API
                3 => "lightcoral",  // U3: implementation
                _ => "white",
            }
        }

        // Helper function to get layer label
        fn layer_label(layer: u8) -> &'static str {
            match layer {
                0 => "U0",
                1 => "U1",
                2 => "U2",
                3 => "U3",
                _ => "U?",
            }
        }

        // Helper function to get kind abbreviation
        fn kind_abbr(kind: NodeKind) -> &'static str {
            match kind {
                NodeKind::Assertion => "A",
                NodeKind::Constraint => "C",
                NodeKind::Scenario => "S",
                NodeKind::Definition => "D",
                NodeKind::Domain => "Dom",
            }
        }

        // Add nodes
        for node in self.graph.node_weights() {
            let layer = node.formality_layer;
            let color = layer_color(layer);
            let layer_lbl = layer_label(layer);
            let kind_lbl = kind_abbr(node.kind);
            let content_short = truncate(&node.content, 50);
            let label = format!("[{}] {} {}", layer_lbl, kind_lbl, content_short);

            dot.push_str(&format!(
                "    \"{}\" [label=\"{}\", fillcolor=\"{}\"];\n",
                escape_dot(&node.id),
                escape_dot(&label),
                color
            ));
        }

        dot.push('\n');

        // Add edges
        for edge_idx in self.graph.edge_indices() {
            if let Some((source_idx, target_idx)) = self.graph.edge_endpoints(edge_idx) {
                if let Some(edge) = self.graph.edge_weight(edge_idx) {
                    if let (Some(source_node), Some(target_node)) = (
                        self.graph.node_weight(source_idx),
                        self.graph.node_weight(target_idx),
                    ) {
                        let edge_style = match edge.kind {
                            EdgeKind::Refines => "solid",
                            EdgeKind::Formalizes => "bold",
                            EdgeKind::DerivesFrom => "dashed",
                            EdgeKind::Transform => "dotted",
                            EdgeKind::Contradicts => "bold, color=red",
                            EdgeKind::DependsOn => "dashed",
                            EdgeKind::Synonym => "dotted, color=gray",
                            EdgeKind::Composes => "solid",
                        };

                        let edge_label = format!("{:?}", edge.kind);

                        dot.push_str(&format!(
                            "    \"{}\" -> \"{}\" [label=\"{}\", style=\"{}\"];\n",
                            escape_dot(&source_node.id),
                            escape_dot(&target_node.id),
                            edge_label,
                            edge_style
                        ));
                    }
                }
            }
        }

        dot.push_str("}\n");
        dot
    }
}

#[derive(Debug, Clone)]
pub struct ComplianceScore {
    pub score: f32,              // Overall compliance score 0.0-1.0
    pub keyword_overlap: f32,    // Semantic keyword similarity
    pub structural_match: f32,   // Structural pattern matching
    pub explanation: String,     // Human-readable explanation
}

#[derive(Debug, Clone)]
pub struct TestCoverage {
    pub total_testable: usize,
    pub with_tests: usize,
    pub coverage_ratio: f32,
    pub nodes_with_tests: Vec<SpecNodeData>,
    pub nodes_without_tests: Vec<SpecNodeData>,
}

#[derive(Debug, Clone)]
pub struct TemporalSnapshot {
    pub timestamp: i64,
    pub nodes: Vec<SpecNodeData>,
    pub edges: Vec<SpecEdgeData>,
    pub node_count: usize,
    pub edge_count: usize,
}

#[derive(Debug, Clone)]
pub struct TemporalDiff {
    pub from_timestamp: i64,
    pub to_timestamp: i64,
    pub added_nodes: Vec<SpecNodeData>,
    pub removed_nodes: Vec<SpecNodeData>,
    pub modified_nodes: Vec<(SpecNodeData, SpecNodeData)>,  // (from, to)
    pub added_edges: Vec<SpecEdgeData>,
    pub removed_edges: Vec<SpecEdgeData>,
}

#[derive(Debug, Clone)]
pub struct HistoryEvent {
    pub timestamp: i64,
    pub event_type: String,  // "created", "modified", "edge_added"
    pub description: String,
