        let history = g.get_node_history(&node_id).unwrap();

        assert_eq!(history.node.id, node_id);
        assert!(!history.events.is_empty());
        assert_eq!(history.events[0].event_type, "created");
    }

    #[test]
    fn get_node_history_shows_edge_additions() {
        let mut g = SpecGraph::new();
        let a = g.add_node("Node A".into(), NodeKind::Assertion, HashMap::new()).id.clone();
        let b = g.add_node("Node B".into(), NodeKind::Assertion, HashMap::new()).id.clone();
        g.add_edge(&a, &b, EdgeKind::Refines, HashMap::new()).unwrap();

        let history = g.get_node_history(&a).unwrap();

        // Should have creation + edge addition
        assert!(history.events.len() >= 2);
        assert!(history.events.iter().any(|e| e.event_type == "edge_added"));
    }

    #[test]
    fn get_node_history_nonexistent_returns_none() {
        let g = SpecGraph::new();
        let history = g.get_node_history("nonexistent");
        assert!(history.is_none());
    }

    #[test]
    fn get_compliance_trend_no_data() {
        let mut g = SpecGraph::new();
        let node = g.add_node("Test".into(), NodeKind::Constraint, HashMap::new()).id.clone();

        let trend = g.get_compliance_trend(&node);
        assert!(trend.is_none());
    }

    #[test]
    fn get_compliance_trend_with_data() {
        let mut g = SpecGraph::new();
        let mut metadata = HashMap::new();
        metadata.insert("compliance_1000".to_string(), "0.5".to_string());
        metadata.insert("compliance_2000".to_string(), "0.7".to_string());
        metadata.insert("compliance_3000".to_string(), "0.9".to_string());

        let node = g.add_node("Test".into(), NodeKind::Constraint, metadata).id.clone();

        let trend = g.get_compliance_trend(&node).unwrap();

        assert_eq!(trend.data_points.len(), 3);
        assert_eq!(trend.data_points[0].timestamp, 1000);
        assert_eq!(trend.data_points[0].score, 0.5);
        assert_eq!(trend.trend_direction, "improving");
    }

    #[test]
    fn get_compliance_trend_degrading() {
        let mut g = SpecGraph::new();
        let mut metadata = HashMap::new();
        metadata.insert("compliance_1000".to_string(), "0.9".to_string());
        metadata.insert("compliance_2000".to_string(), "0.5".to_string());

        let node = g.add_node("Test".into(), NodeKind::Constraint, metadata).id.clone();

        let trend = g.get_compliance_trend(&node).unwrap();

        assert_eq!(trend.trend_direction, "degrading");
    }

    #[test]
    fn get_compliance_trend_stable() {
        let mut g = SpecGraph::new();
        let mut metadata = HashMap::new();
        metadata.insert("compliance_1000".to_string(), "0.7".to_string());
        metadata.insert("compliance_2000".to_string(), "0.72".to_string());

        let node = g.add_node("Test".into(), NodeKind::Constraint, metadata).id.clone();

        let trend = g.get_compliance_trend(&node).unwrap();

        assert_eq!(trend.trend_direction, "stable");
    }

    #[test]
    fn detect_inter_universe_inconsistencies_empty() {
        let g = SpecGraph::new();
        let inconsistencies = g.detect_inter_universe_inconsistencies();
        assert!(inconsistencies.is_empty());
    }

    #[test]
    fn detect_inter_universe_inconsistencies_with_transform() {
        let mut g = SpecGraph::new();

        // Create nodes in different universes
        let mut metadata_ui = HashMap::new();
        metadata_ui.insert("universe".to_string(), "ui".to_string());
        let ui_node_id = g
            .add_node(
                "User must authenticate".into(),
                NodeKind::Constraint,
                metadata_ui,
            )
            .id
            .clone();

        let mut metadata_api = HashMap::new();
        metadata_api.insert("universe".to_string(), "api".to_string());
        let api_node_id = g
            .add_node(
                "Authentication is forbidden".into(),
                NodeKind::Constraint,
                metadata_api,
            )
            .id
            .clone();

        // Add Transform edge between them
        g.add_edge(&ui_node_id, &api_node_id, EdgeKind::Transform, HashMap::new())
            .ok();

        let inconsistencies = g.detect_inter_universe_inconsistencies();

        // Should detect contradiction between "must" and "forbidden"
        assert!(!inconsistencies.is_empty());
        assert_eq!(inconsistencies[0].universe_a, "ui");
        assert_eq!(inconsistencies[0].universe_b, "api");
    }

    #[test]
    fn detect_inter_universe_inconsistencies_missing_transform() {
        let mut g = SpecGraph::new();

        // Create nodes in different universes with related content
        let mut metadata_ui = HashMap::new();
        metadata_ui.insert("universe".to_string(), "ui".to_string());
        g.add_node(
            "Button click triggers authentication process".into(),
            NodeKind::Scenario,
            metadata_ui,
        );

        let mut metadata_api = HashMap::new();
        metadata_api.insert("universe".to_string(), "api".to_string());
        g.add_node(
            "Authentication process validates credentials".into(),
            NodeKind::Constraint,
            metadata_api,
        );

        // No Transform edge between them
        let inconsistencies = g.detect_inter_universe_inconsistencies();

        // Should detect missing transformation function
        let missing_transform = inconsistencies
            .iter()
            .any(|i| i.transform_path.is_empty() && i.explanation.contains("Missing transformation"));
        assert!(missing_transform);
    }

    #[test]
    fn update_node_metadata_works() {
        let mut g = SpecGraph::new();
        let node = g.add_node("Test".into(), NodeKind::Assertion, HashMap::new());
        let node_id = node.id.clone();

        let updated = g.update_node_metadata(&node_id, "universe".to_string(), "test".to_string());
        assert!(updated.is_some());

        let retrieved = g.get_node(&node_id).unwrap();
        assert_eq!(retrieved.metadata.get("universe"), Some(&"test".to_string()));
    }
}

